"""Builds pixelpare-icon-macos.svg by inlining the iOS master onto Apple's macOS 824px plate."""
import re, pathlib
here = pathlib.Path(__file__).parent
src = (here / "pixelpare-icon.svg").read_text()
inner = re.search(r"<svg[^>]*>(.*)</svg>", src, re.S).group(1)
out = f'''<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 1024 1024">
  <!-- GENERATED by gen-macos-svg.py from pixelpare-icon.svg - do not edit by hand.
       macOS: artwork on an 824x824 rounded plate (x/y 100, rx 185) with drop shadow, transparent canvas. -->
  <defs>
    <clipPath id="plate"><rect x="100" y="100" width="824" height="824" rx="185"/></clipPath>
    <filter id="plateShadow" x="-10%" y="-10%" width="120%" height="125%"><feDropShadow dx="0" dy="10" stdDeviation="14" flood-color="#000" flood-opacity=".3"/></filter>
  </defs>
  <rect x="100" y="100" width="824" height="824" rx="185" fill="#4F6BF0" filter="url(#plateShadow)"/>
  <g clip-path="url(#plate)"><g transform="translate(100 100) scale(.8046875)">{inner}</g></g>
</svg>
'''
(here / "pixelpare-icon-macos.svg").write_text(out)
